// Cache-aside pattern with Redis (Node.js / ioredis)
import { Redis } from 'ioredis';
const redis = new Redis(process.env.REDIS_URL);
const TTL_SECONDS = 300; // 5-minute cache

async function getUserById(userId) {
  const cacheKey = `user:${userId}`;

  // 1. Check cache first
  const cached = await redis.get(cacheKey);
  if (cached) {
    return JSON.parse(cached); // cache hit — ~0.5ms
  }

  // 2. Cache miss — query the database
  const user = await db.query(
    'SELECT id, name, email FROM users WHERE id = $1',
    [userId]
  );

  // 3. Populate cache for future requests
  if (user) {
    await redis.setex(cacheKey, TTL_SECONDS, JSON.stringify(user));
  }

  return user; // ~20ms on first request, <1ms afterward
}

// Invalidate on update
async function updateUserEmail(userId, newEmail) {
  await db.query(
    'UPDATE users SET email = $1 WHERE id = $2',
    [newEmail, userId]
  );
  await redis.del(`user:${userId}`); // force re-fetch next read
}

// Scalability checklist — patterns and their trade-offs

// 1. Stateless app servers
//    Requirement: sessions in Redis/DB, not server memory
//    Enables: horizontal scaling, rolling deploys, zero-downtime restarts

// 2. Read replicas
//    Requirement: replica lag awareness (stale reads okay?)
//    Rule of thumb: route 80% of traffic to replicas, 20% (writes) to primary

// 3. CDN for static assets
//    Set Cache-Control: public, max-age=31536000, immutable on versioned files
//    Set Cache-Control: no-store on personalized API responses

// 4. Database connection pooling (e.g., PgBouncer)
//    Problem: 1000 app instances × 10 connections = 10,000 DB connections
//    Solution: pool proxy limits actual DB connections to ~100

// 5. Async work for slow operations
//    Bad:  await sendEmail()  // blocks HTTP response for 500ms
//    Good: queue.publish('send-email', payload); return 202 Accepted
